import{_ as a,C as o,o as d,c as s,E as n,a2 as i}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.7","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.7","outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.7/part-01.md","filePath":"zh/publications/implementation-case-i0.7/part-01.md","lastUpdated":1786282064000}'),l={name:"zh/publications/implementation-case-i0.7/part-01.md"};function p(r,t,c,h,u,C){const e=o("ArticleCover");return d(),s("div",null,[n(e,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"覆盖 TMPA Core S0.5 全部准则的 CodeFlowMu V1.4.1 锁定产品运行，并保留 WP-13 治理证据。",version:"I0.7",status:"S0.5 产品证据草稿 · 14/14 PASS",languageHref:"/en/publications/implementation-case-i0.7",languageLabel:"English"}),t[0]||(t[0]=i(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="tmpa-core-s0-5、fcop-3-2-4、codeflowmu-v1-4-1-与-wp-13" tabindex="-1">TMPA Core S0.5、FCoP 3.2.4、CodeFlowMu V1.4.1 与 WP-13 <a class="header-anchor" href="#tmpa-core-s0-5、fcop-3-2-4、codeflowmu-v1-4-1-与-wp-13" aria-label="Permalink to &quot;TMPA Core S0.5、FCoP 3.2.4、CodeFlowMu V1.4.1 与 WP-13&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> 草稿 I0.7<br><strong>状态：</strong> 作者制作的实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>受测产品：</strong> CodeFlowMu V1.4.1，Commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code><br><strong>证据采集：</strong> 2026-08-09，Asia/Shanghai<br><strong>正式证据包：</strong> <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</code><br><strong>压缩包 SHA-256：</strong> <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code><br><strong>权威边界：</strong> 本报告属于证据性、非规范性文档；只有 Core Specification 定义 TMPA 要求。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I0.7 使用公开、Commit 锁定的 CodeFlowMu V1.4.1 源码，执行 TMPA Core S0.5 的全部十四项强制符合性准则。固定源码与测试 Bundle 下，产品矩阵为 <strong>14 PASS、0 PARTIAL、0 NOT RUN、0 FAIL</strong>。外部产品夹具通过 15/15 项断言；CodeFlowMu 内置 TMPA 套件通过 19/19；Runtime 为 1,446 passed / 0 failed / 1 skipped；Shell 为 775/775；FCoP 为 1,210 passed / 2 skipped；Protocol 与各项 Typecheck 均成功退出。</p><p>该结果升级了 I0.6 本地基线及保留的 CodeFlowMu V1.4.0 修复前基线。V1.4.0 为 12 PASS / 2 FAIL：C06 未能把生命周期完成与独立验收分开，C12 允许未授权裁决清除复核冲突。V1.4.1 修复这两个边界，同时没有弱化 C03 或 C10。V1.4.0 压缩包仅作为历史证据保留，不属于 I0.7 正式出版主包。</p><p>当前最强、且不越界的结论是：<strong>固定 Bundle 下由作者本地 demonstrated 的产品符合性</strong>。它不是独立认证、独立采用、任意输入上的形式证明，也不证明多智能体幻觉已被消除。WP-13 仍是独立的有限案例，只演示对最初未核验完成声明的证据门禁与角色分离复核。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>I0.7 回答以下问题：</p><ol><li>锁定的 CodeFlowMu V1.4.1 产品运行是否逐项满足 S0.5 的 C01–C14？</li><li>V1.4.1 是否在不混并其他治理准则的条件下关闭 V1.4.0 的两项失败？</li><li>如何表述 TMPA、FCoP、CodeFlowMu 与 WP-13，避免混淆理论、协议、应用与案例证据？</li><li>在结果可称为独立验证或独立采用之前，还存在哪些边界？</li></ol><p>裁决单位是固定源码与证据 Bundle 上、绑定具体准则的主张。四个成熟度层级严格分开：</p><table tabindex="0"><thead><tr><th>层级</th><th>I0.7 中的含义</th><th style="text-align:right;">是否达到</th></tr></thead><tbody><tr><td>Specified</td><td>由 TMPA Core S0.5 规范定义</td><td style="text-align:right;">是</td></tr><tr><td>Implemented</td><td>产品中存在相应机制</td><td style="text-align:right;">是</td></tr><tr><td>Demonstrated</td><td>作者运行产生了可检查证据</td><td style="text-align:right;">是，仅限本 Bundle 的 C01–C14</td></tr><tr><td>Independently Adopted</td><td>独立组织采用并验证该机制</td><td style="text-align:right;">否</td></tr></tbody></table><h1 id="_2-架构与证据边界" tabindex="-1">2. 架构与证据边界 <a class="header-anchor" href="#_2-架构与证据边界" aria-label="Permalink to &quot;2. 架构与证据边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ 理论与治理模型</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>        ↓ 规范对象、Reader 与符合性契约</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>        ↓ 基于文件的协同 Profile 与参考实现</span></span>
<span class="line"><span>CodeFlowMu 应用</span></span>
<span class="line"><span>        ↓ Runtime、角色、工作流、恢复与审计行为</span></span>
<span class="line"><span>WP-13 有限现场案例</span></span></code></pre></div><p>TMPA 是架构与治理理论。FCoP 是可复用的基于文件的协同协议，不是应用程序，也不是某个安装包主张；<code>fcop</code> 与 <code>fcop-mcp</code> 是该协议的参考实现。CodeFlowMu 是本次评估的下游应用。WP-13 是该工程谱系中的一个有限工作流案例，不能替代完整的 C01–C14 产品运行。</p><p>概念依赖与历史形成过程保持分离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>概念关系：TMPA → FCoP → CodeFlowMu / 其他应用</span></span>
<span class="line"><span>历史关系：小典实践 → 早期 TMPA → FCoP 提取</span></span>
<span class="line"><span>                               → CodeFlowMu → 当前 TMPA 形式化</span></span></code></pre></div><p>小典 AI 仍属于工程谱系和候选现场证据来源。I0.7 不增加小典符合性主张，因为本次没有执行固定的小典 S0.5 Bundle。</p><h1 id="_3-锁定来源与证据设计" tabindex="-1">3. 锁定来源与证据设计 <a class="header-anchor" href="#_3-锁定来源与证据设计" aria-label="Permalink to &quot;3. 锁定来源与证据设计&quot;">​</a></h1><table tabindex="0"><thead><tr><th>来源</th><th>锁定标识</th><th>I0.7 中的作用</th><th>边界</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.5</td><td>C01–C14 规范目标</td><td>规范，不是产品证据</td></tr><tr><td>CodeFlowMu</td><td>V1.4.1，Commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code></td><td>受测产品</td><td>可公开获取；初始化前为干净 detached checkout</td></tr><tr><td>FCoP</td><td>3.2.4，Commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>协议与参考基线</td><td>可公开获取的干净 checkout</td></tr><tr><td>外部夹具</td><td>15 项强制断言</td><td>产品级 C01–C14 评估</td><td>固定测试构造，不是任意输入证明</td></tr><tr><td>WP-13 V3</td><td>已出版证据包</td><td>多 Agent 证据门禁案例</td><td>独立的作者制作案例证据</td></tr></tbody></table><p>原 CodeFlowMu 与 FCoP 本地工作树存在未提交内容，但证据采集未修改它们；测试使用固定的 detached checkout。CodeFlowMu 在产品初始化前是干净的，初始化生成文件另行记录于 <code>manifests/codeflowmu-post-initialization-status.txt</code>。证据采集期间没有 Push、Release 或 Tag。</p><p>正式公开包只包括 V1.4.1 ZIP 与外部 SHA-256 文件。V1.4.0 包记录 12 PASS / 2 FAIL 的修复前状态，仅作为历史证据保留；除非审稿人要求对照，否则不进入 I0.7 正式主包。</p>`,22))])}const b=a(l,[["render",p]]);export{m as __pageData,b as default};
